    for (@cmd_lines) {
        if (/\n/) {
            print AC2 $_;
        } else {
            print AC2 $_, "\n";
        }
    }
    close AC2;

    return 1;
}

sub cache_fw_policy() {
    my $file = shift;
    open FWP, "< $file" or die "[*] Could not open $file: $!";
    while (<FWP>) {
        ### 3   ACCEPT   tcp  --  127.0.0.2...
        ### Since we use the policy cache to detect duplicate rules,
        ### don't allow the rule number itself to make each rule
        ### unique by default
        if (/^\d+\s+(.*)/) {
            $cached_fw_policy{$1} = '';
        }
    }
    close FWP;
}

