                    }
                }
            }

        } elsif ($line =~ /Run time: ([\d\.]+) minutes/) {
            my $total_elapsed_seconds = time() - $start_time;
            my $total_elapsed_minutes = sprintf "%.2f", ($total_elapsed_seconds / 60);
